import unittest

from rate_limiter import TokenBucketRateLimiter


class TestTokenBucketRateLimiter(unittest.TestCase):
    def test_initial_capacity(self):
        limiter = TokenBucketRateLimiter(capacity=3, refill_rate=1, clock=lambda: 0.0)
        for _ in range(3):
            self.assertTrue(limiter.allow())
        self.assertFalse(limiter.allow())

    def test_consumption_and_rejection(self):
        limiter = TokenBucketRateLimiter(capacity=5, refill_rate=1, clock=lambda: 0.0)
        self.assertTrue(limiter.allow(2))
        self.assertTrue(limiter.allow(2))
        self.assertFalse(limiter.allow(2))
        self.assertTrue(limiter.allow(1))

    def test_replenishment_over_simulated_time(self):
        limiter = TokenBucketRateLimiter(capacity=2, refill_rate=2, clock=lambda: 0.0)
        self.assertTrue(limiter.allow(2))
        self.assertFalse(limiter.allow(1))
        self.assertTrue(limiter.allow(1, now=0.5))
        self.assertFalse(limiter.allow(1, now=0.5))
        self.assertTrue(limiter.allow(1, now=1.0))

    def test_burst_capacity_handling(self):
        limiter = TokenBucketRateLimiter(
            capacity=1, refill_rate=1, burst_capacity=4, clock=lambda: 0.0
        )
        for _ in range(4):
            self.assertTrue(limiter.allow())
        self.assertFalse(limiter.allow())


if __name__ == "__main__":
    unittest.main()

